// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../libraries/ACPTypes.sol";

/**
 * @title IMemoManager
 * @dev Interface for the Memo Manager module
 */
interface IMemoManager {

    // Events
    event NewMemo(
        uint256 indexed memoId,
        uint256 indexed jobId,
        address indexed sender,
        ACPTypes.MemoType memoType,
        ACPTypes.JobPhase nextPhase,
        string content
    );

    event MemoSigned(
        uint256 indexed memoId,
        address indexed approver,
        bool approved,
        string reason
    );

    event PayableMemoExecuted(
        uint256 indexed memoId,
        uint256 indexed jobId,
        address indexed executor,
        uint256 amount
    );

    /**
     * @dev Create a new memo
     * @param jobId The job ID this memo belongs to
     * @param sender Address creating the memo
     * @param content Memo content
     * @param memoType Type of memo
     * @param isSecured Whether the memo is secured
     * @param nextPhase The next phase to transition to
     * @return memoId The ID of the created memo
     */
    function createMemo(
        uint256 jobId,
        address sender,
        string calldata content,
        ACPTypes.MemoType memoType,
        bool isSecured,
        ACPTypes.JobPhase nextPhase
    ) external returns (uint256 memoId);

    /**
     * @dev Create a payable memo with payment details
     * @param jobId The task ID
     * @param sender Address creating the memo
     * @param content Memo content
     * @param memoType Type of memo
     * @param payableDetails Payment details
     * @return memoId The ID of the created memo
     */
    function createPayableMemo(
        uint256 jobId,
        address sender,
        string calldata content,
        ACPTypes.MemoType memoType,
        bool isSecured,
        ACPTypes.JobPhase nextPhase,
        ACPTypes.PayableDetails calldata payableDetails,
        uint256 expiredAt
    ) external returns (uint256 memoId);

    /**
     * @dev Approve or reject a memo
     * @param memoId The memo ID
     * @param approved Whether the memo is approved
     * @param reason Reason for approval/rejection
     */
    function approveMemo(
        uint256 memoId,
        address sender,
        bool approved,
        string calldata reason
    ) external;

     function signMemo(
        uint256 memoId,
        address sender,
        bool isApproved,
        string calldata reason
    ) external returns (uint256 jobId);

    /**
     * @dev Execute a payable memo (transfer funds)
     * @param memoId The memo ID
     */
    function executePayableMemo(uint256 memoId) external;

    /**
     * @dev Get memo details
     * @param memoId The memo ID
     * @return memo The memo struct
     */
    function getMemo(uint256 memoId) external view returns (ACPTypes.Memo memory memo);

    /**
     * @dev Get all memos for a task
     * @param jobId The task ID
     * @param offset Pagination offset
     * @param limit Pagination limit
     * @return memos Array of memos
     * @return total Total number of memos
     */
    function getJobMemos(
        uint256 jobId,
        uint256 offset,
        uint256 limit
    ) external view returns (ACPTypes.Memo[] memory memos, uint256 total);

    /**
     * @dev Get memos by type for a task
     * @param jobId The task ID
     * @param memoType The memo type to filter by
     * @param offset Pagination offset
     * @param limit Pagination limit
     * @return memos Array of memos
     * @return total Total number of memos
     */
    function getJobMemosByType(
        uint256 jobId,
        ACPTypes.MemoType memoType,
        uint256 offset,
        uint256 limit
    ) external view returns (ACPTypes.Memo[] memory memos, uint256 total);

    /**
     * @dev Get payable details for a memo
     * @param memoId The memo ID
     * @return details The payable details
     */
    function getPayableDetails(uint256 memoId) external view returns (ACPTypes.PayableDetails memory details);

    /**
     * @dev Get memo with its payable details
     * @param memoId The memo ID
     * @return memo The memo struct
     * @return payableDetails The payable details
     */
    function getMemoWithPayableDetails(uint256 memoId) external view returns (
        ACPTypes.Memo memory memo,
        ACPTypes.PayableDetails memory payableDetails
    );

    /**
     * @dev Check if memo requires approval
     * @param memoId The memo ID
     * @return requiresApproval True if memo requires approval
     */
    function requiresApproval(uint256 memoId) external view returns (bool requiresApproval);

    /**
     * @dev Check if user can approve memo
     * @param memoId The memo ID
     * @param user The user address
     * @return canApprove True if user can approve the memo
     */
    function canApproveMemo(uint256 memoId, address user) external view returns (bool canApprove);

    /**
     * @dev Check if user can sign memo
     * @param memoId The memo ID
     * @param user The user address
     * @return canSign True if user can sign the memo
     */
    function isMemoSigner(uint256 memoId, address user) external view returns (bool canSign);

    /**
     * @dev Check if memo is payable
     * @param memoId The memo ID
     * @return isPayable True if memo is payable
     */
    function isPayable(uint256 memoId) external view returns (bool isPayable);

    /**
     * @dev Get memo approval status
     * @param memoId The memo ID
     * @return isApproved True if memo is approved
     * @return approvedBy Address that approved the memo
     * @return approvedAt Timestamp when memo was approved
     */
    function getMemoApprovalStatus(uint256 memoId) external view returns (
        bool isApproved,
        address approvedBy,
        uint256 approvedAt
    );

    /**
     * @dev Bulk approve memos
     * @param memoIds Array of memo IDs
     * @param approved Whether memos are approved
     * @param reason Reason for approval/rejection
     */
    function bulkApproveMemos(
        uint256[] calldata memoIds,
        bool approved,
        string calldata reason
    ) external;

    /**
     * @dev Update memo content (if allowed)
     * @param memoId The memo ID
     * @param newContent New content for the memo
     */
    function updateMemoContent(uint256 memoId, string calldata newContent) external;
}

contracts/acp/interfaces/IPaymentManager.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "../libraries/ACPTypes.sol";

/**
 * @title IPaymentManager
 * @dev Interface for the Payment Manager module
 */
interface IPaymentManager {

    // Events
    event BudgetEscrowed(
        uint256 indexed jobId,
        address indexed client,
        uint256 amount,
        address token
    );

    event PaymentReleased(
        uint256 indexed jobId,
        address indexed recipient,
        uint256 amount,
        address token,
        string reason
    );

    event FeeCollected(
        uint256 indexed jobId,
        address indexed payer,
        uint256 amount,
        address token,
        string feeType
    );

    event PaymentRefunded(
        uint256 indexed jobId,
        address indexed client,
        uint256 amount,
        address token,
        string reason
    );

    event PayableFundsEscrowed(
        uint256 indexed memoId,
        address indexed sender,
        address token,
        uint256 amount,
        uint256 feeAmount
    );

    event PayableMemoExecuted(
        uint256 indexed memoId,
        address indexed sender,
        address indexed recipient,
        address token,
        uint256 amount
    );

    event PayableFeeDistributed(
        uint256 indexed memoId,
        address indexed payer,
        address indexed recipient,
        uint256 amount
    );

    event PayableFeeCollected(
        uint256 indexed memoId,
        address indexed payer,
        uint256 amount
    );

    /**
     * @dev Escrow account budget
     * @param jobId The job ID
     */
    function escrowAccountBudget(uint256 jobId) external;

    /**
     * @dev Release payment for completed work
     * @param jobId The account ID
     * @param recipient Address to receive payment
     * @param amount Amount to release
     * @param reason Reason for payment release
     */
    function releasePayment(
        uint256 jobId,
        address recipient,
        uint256 amount,
        address evaluator,
        string calldata reason
    ) external;

    /**
     * @dev Refund escrowed budget to client
     * @param jobId The account ID
     * @param amount Amount to refund
     * @param reason Reason for refund
     */
    function refundBudget(
        uint256 jobId,
        uint256 amount,
        address recipient,
        string calldata reason
    ) external;

    /**
     * @dev Process platform and evaluator fees
     * @param jobId The account ID
     * @param amount Amount to process fees from
     * @return netAmount Amount after fees
     */
    function processFees(
        uint256 jobId,
        uint256 amount
    ) external returns (uint256 netAmount);

    /**
     * @dev Get escrowed amount for an account
     * @param jobId The account ID
     * @return amount Escrowed amount
     * @return token Token address
     */
    function getEscrowedAmount(uint256 jobId) external view returns (uint256 amount, address token);

    /**
     * @dev Get available balance for release
     * @param jobId The account ID
     * @return available Available amount for release
     */
    function getAvailableBalance(uint256 jobId) external view returns (uint256 available);

    /**
     * @dev Calculate platform fees
     * @param amount Amount to calculate fees from
     * @return platformFee Platform fee amount
     * @return evaluatorFee Evaluator fee amount
     */
    function calculateFees(uint256 amount) external view returns (uint256 platformFee, uint256 evaluatorFee);

    /**
     * @dev Emergency withdrawal (admin only)
     * @param token Token to withdraw
     * @param amount Amount to withdraw
     * @param recipient Recipient of withdrawal
     */
    function emergencyWithdraw(
        address token,
        uint256 amount,
        address recipient
    ) external;

    /**
     * @dev Set payment configurations
     * @param platformFeeBP Platform fee in basis points
     * @param evaluatorFeeBP Evaluator fee in basis points
     * @param platformTreasury Platform treasury address
     */
    function setPaymentConfig(
        uint256 platformFeeBP,
        uint256 evaluatorFeeBP,
        address platformTreasury
    ) external;

    /**
     * @dev Process payment for PAYABLE_TRANSFER_ESCROW memo
     * @param memoId The memo ID
     * @param sender The sender of the payment
     * @param payableDetails Payment details
     */

    function processPayableTransferEscrowMemo(
        uint256 memoId,
        address sender,
        ACPTypes.PayableDetails calldata payableDetails
    ) external;

    /**
     * @dev Execute payment for non-escrow payable memos
     * Called by ACP contract when memo is signed and approved
     * @param memoId The memo ID
     * @param payer The payer address
     * @param payableDetails Payment details
     * @param provider The provider address
     */
    function executePayableTransfer(
        uint256 memoId,
        address payer,
        ACPTypes.PayableDetails calldata payableDetails,
        address provider
    ) external;

    /**
     * @dev Check if account has sufficient escrow
     * @param jobId The account ID
     * @param amount Amount to check
     * @return hasSufficient True if account has sufficient escrow
     */
    function hasSufficientEscrow(uint256 jobId, uint256 amount) external view returns (bool hasSufficient);

    /**
     * @dev Set escrow details for an account
     * @param jobId The account ID
     * @param amount Escrow amount
     * @param token Escrow token
     */
    function setEscrowDetails(
        uint256 jobId,
        uint256 amount,
        address token
    ) external;

    /**
     * @dev Refund escrowed memo funds
     * @param memoId The memo ID
     * @param recipient Recipient of the refund
     * @param token Token to refund
     * @param amount Amount to refund
     * @param feeAmount Fee amount to refund
     */
    function refundEscrowedMemoFunds(
        uint256 memoId,
        address recipient,
        address token,
        uint256 amount,
        uint256 feeAmount
    ) external;
}

contracts/acp/libraries/ACPTypes.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title ACPTypes
 * @dev Library containing data structures for the modular ACP system
 */
library ACPTypes {

    enum JobPhase {
        REQUEST,        // 0 - Initial job request
        NEGOTIATION,    // 1 - Terms negotiation
        TRANSACTION,    // 2 - Work in progress/transaction phase
        EVALUATION,     // 3 - Work evaluation
        COMPLETED,      // 4 - Successfully completed
        REJECTED,       // 5 - Rejected or failed
        EXPIRED         // 6 - Expired without completion
    }

    enum MemoType {
        MESSAGE,                    // 0 - Text message
        CONTEXT_URL,               // 1 - URL for context
        IMAGE_URL,                 // 2 - Image URL
        VOICE_URL,                 // 3 - Voice/audio URL
        OBJECT_URL,                // 4 - Object/file URL
        TXHASH,                    // 5 - Transaction hash reference
        PAYABLE_REQUEST,           // 6 - Payment request
        PAYABLE_TRANSFER,          // 7 - Direct payment transfer
        PAYABLE_TRANSFER_ESCROW,   // 8 - Escrowed payment transfer
        NOTIFICATION,        // 9 - Notification
        PAYABLE_NOTIFICATION     // 10 - Payable notification
    }

    enum FeeType {
        NO_FEE,         // 0 - No fee
        IMMEDIATE_FEE,  // 1 - Fee paid immediately
        DEFERRED_FEE    // 2 - Fee deferred to account completion
    }

    struct Account {
        uint256 id;
        address client;
        address provider;
        uint256 createdAt;
        string metadata;
        uint256 jobCount;
        uint256 completedJobCount;
        bool isActive;
    }

    struct Job {
        uint256 id;
        uint256 accountId;
        address client;
        address provider;
        address evaluator;
        address creator;
        uint256 budget;
        IERC20 jobPaymentToken;
        JobPhase phase;
        uint256 expiredAt;
        uint256 createdAt;
        uint256 memoCount;
        string metadata;
        uint256 amountClaimed;
    }

    struct Memo {
        uint256 id;
        uint256 jobId;
        address sender;
        string content;
        MemoType memoType;
        uint256 createdAt;
        bool isApproved;
        address approvedBy;
        uint256 approvedAt;
        bool requiresApproval;
        string metadata;
        bool isSecured;
        JobPhase nextPhase;
        uint256 expiredAt;
    }

    struct PayableDetails {
        address token;
        uint256 amount;
        address recipient;
        uint256 feeAmount;
        FeeType feeType;
        bool isExecuted;
        uint256 expiredAt;
    }

    // Utility functions for type validation
    function isValidJobPhase(JobPhase phase) internal pure returns (bool) {
        return uint8(phase) <= uint8(JobPhase.EXPIRED);
    }

    function isValidMemoType(MemoType memoType) internal pure returns (bool) {
        return uint8(memoType) <= uint8(MemoType.PAYABLE_NOTIFICATION);
    }

    function isPayableMemoType(MemoType memoType) internal pure returns (bool) {
        return memoType == MemoType.PAYABLE_REQUEST ||
               memoType == MemoType.PAYABLE_TRANSFER ||
               memoType == MemoType.PAYABLE_TRANSFER_ESCROW ||
               memoType == MemoType.PAYABLE_NOTIFICATION;
    }

    function isNotificationMemoType(MemoType memoType) internal pure returns (bool) {
        return memoType == MemoType.NOTIFICATION || memoType == MemoType.PAYABLE_NOTIFICATION;
    }

    // Helper function to calculate phase progression
    function canProgressToPhase(JobPhase current, JobPhase target) internal pure returns (bool) {
        if (target == JobPhase.REJECTED || target == JobPhase.EXPIRED) {
            return true; // Can always reject or expire
        }

        if (current == JobPhase.REQUEST) {
            return target == JobPhase.NEGOTIATION || target == JobPhase.TRANSACTION;
        } else if (current == JobPhase.NEGOTIATION) {
            return target == JobPhase.TRANSACTION;
        } else if (current == JobPhase.TRANSACTION) {
            return target == JobPhase.EVALUATION;
        } else if (current == JobPhase.EVALUATION) {
            return target == JobPhase.COMPLETED;
        }

        return false;
    }
}

